import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { ChevronDown } from "@exp-textura/icons";

import { MultiSelectClasses } from "../multi-select.styles";

export const MultiSelectIcon = forwardRef<
  HTMLSpanElement,
  { className?: string; children?: React.ReactNode }
>(({ children = <ChevronDown />, className, ...props }, ref) => {
  return (
    <span className={clsx(MultiSelectClasses.icon, className)} {...props} ref={ref}>
      {children}
    </span>
  );
});
MultiSelectIcon.displayName = "MultiSelect.Icon";
